FLASHCARDS.forEach(card=>searchIndex.push({title:card.q,area:'Flashcards → '+card.tag,text:searchableText(card.a+' '+card.excerpt+' printed page '+card.printed+' PDF page '+card.pdf),open:()=>{nav('flashcards');flashFilter='all';currentFlashIndex=FLASHCARDS.findIndex(x=>x.id===card.id);flashRevealed=false;flashcardsPage()}}));
document.getElementById('dueCount').textContent=flashcardsDueCount();
let currentFlashIndex=0,flashRevealed=false,flashFilter='due';
function flashDue(card){return window.MINDPLAN_SPACED_REVIEW.isDue(flashState[card.id])}
function flashcardsDueCount(){return FLASHCARDS.filter(flashDue).length}
function flashcardsPage(){const due=FLASHCARDS.filter(flashDue);const deck=flashFilter==='all'?FLASHCARDS:flashFilter==='new'?FLASHCARDS.filter(c=>!flashState[c.id]):due;currentFlashIndex=Math.min(currentFlashIndex,Math.max(0,deck.length-1));const card=deck[currentFlashIndex];document.getElementById('dueCount').textContent=flashcardsDueCount();main.innerHTML=`<div class="eyebrow">Active recall · device-local spaced review</div><h1>Flashcards</h1><p class="muted">Recall the answer before revealing it. Mark how difficult retrieval felt; the next review date is stored only in this browser. Again schedules another review today; Difficult grows the interval cautiously; Mastered expands the interval progressively (up to 60 days). Ratings update a device-local schedule and short review history. This is a transparent study aid, not a validated learning algorithm.</p><div class="flash-toolbar"><div class="flash-filters">${[['due','Due now'],['new','New'],['all','All cards']].map(x=>`<button class="btn ${flashFilter===x[0]?'primary':'secondary'}" data-flash-filter="${x[0]}">${x[1]}</button>`).join('')}</div><div class="stats"><div class="stat"><strong>${FLASHCARDS.length}</strong><span>Total cards</span></div><div class="stat"><strong>${flashcardsDueCount()}</strong><span>Due now</span></div><div class="stat"><strong>${Object.values(flashState).filter(s=>s.status==='mastered').length}</strong><span>Mastered</span></div></div></div>${card?`<section class="card flashcard"><div class="eyebrow">${esc(card.tag)} · Card ${currentFlashIndex+1} of ${deck.length}</div><h2>${esc(card.q)}</h2>${flashRevealed?`<div class="flash-answer"><h3>Answer</h3><p>${esc(card.a)}</p>${cite({label:'source-says',claim:card.a,citation:{printedPages:card.printed,pdfPages:card.pdf,verificationStatus:'Source-linked review card'},excerpt:card.excerpt})}</div><div class="button-row review-buttons"><button class="btn secondary" data-rate="again">↻ Again</button><button class="btn secondary" data-rate="difficult">◷ Difficult</button><button class="btn primary" data-rate="mastered">✓ Mastered</button></div>`:`<div class="flash-hidden"><p>Try to answer from memory before revealing.</p><button class="btn primary" data-action="reveal">Reveal answer</button></div>`}<div class="button-row"><button class="btn secondary" data-action="prev-flash" ${currentFlashIndex===0?'disabled':''}>← Previous</button><button class="btn secondary" data-action="next-flash" ${currentFlashIndex>=deck.length-1?'disabled':''}>Next →</button></div><p class="inline-note">Status: ${esc(flashState[card.id]?.status||'New')}${flashState[card.id]?.due?' · Next review '+new Date(flashState[card.id].due).toLocaleDateString():''}</p></section>`:`<section class="card empty"><h2>No cards due in this deck</h2><p>Switch to All cards or New to review the full set.</p><button class="btn primary" data-flash-filter="all">Review all cards</button></section>`}<div class="callout warning">Source scope: content is based on the National Mental Health Strategic Plan 2019–2023. Its targets are historical; this deck does not claim they were achieved.</div><footer>${attribution()}</footer>`;main.querySelectorAll('[data-flash-filter]').forEach(b=>b.addEventListener('click',()=>{flashFilter=b.dataset.flashFilter;currentFlashIndex=0;flashRevealed=false;flashcardsPage()}));main.querySelector('[data-action="reveal"]')?.addEventListener('click',()=>{flashRevealed=true;flashcardsPage();flashRevealed=true;const revealBtn=main.querySelector('[data-action="reveal"]');if(revealBtn)revealBtn.remove();});main.querySelector('[data-action="prev-flash"]')?.addEventListener('click',()=>{currentFlashIndex=Math.max(0,currentFlashIndex-1);flashRevealed=false;flashcardsPage()});main.querySelector('[data-action="next-flash"]')?.addEventListener('click',()=>{currentFlashIndex=Math.min(deck.length-1,currentFlashIndex+1);flashRevealed=false;flashcardsPage()});main.querySelectorAll('[data-rate]').forEach(b=>b.addEventListener('click',()=>{flashState=window.MINDPLAN_SPACED_REVIEW.reviewEvent(flashState,card.id,b.dataset.rate,new Date());saveFlashState();if(flashFilter==='all'||b.dataset.rate==='again')currentFlashIndex=Math.min(currentFlashIndex+1,Math.max(0,deck.length-1));else currentFlashIndex=Math.min(currentFlashIndex,Math.max(0,deck.length-1));flashRevealed=false;document.getElementById('dueCount').textContent=flashcardsDueCount();flashcardsPage();toast('Flashcard review saved locally')}));}
function openSource(ref){const dialog=document.getElementById('sourceDialog'),body=document.getElementById('sourceDialogBody');sourceOpener=document.activeElement;const pdfPage=String(ref.pdfPages||'').match(/\d+/)?.[0]||'';const pdfUrl='https://doh.gov.ph/wp-content/uploads/2023/08/Mental-Health-Strategic-Plan.pdf'+(pdfPage?'#page='+pdfPage:'');document.getElementById('sourceDialogTitle').textContent=ref.title||'National Mental Health Strategic Plan 2019–2023';body.innerHTML=`<div class="source-meta"><span class="tag">${esc(ref.label==='source-says'?'Source says':'Learning note')}</span><span class="tag">Printed p. ${esc(ref.printedPages||'not specified')}</span><span class="tag">PDF p. ${esc(ref.pdfPages||'not specified')}</span></div><h3>Claim or summary</h3><p>${esc(ref.claim||'')}</p>${ref.excerpt?`<h3>Source excerpt / linked note</h3><blockquote>${esc(ref.excerpt)}</blockquote>`:''}<p class="muted small">Reference: Philippine Council for Mental Health, <i>National Mental Health Strategic Plan 2019–2023</i>. Page mapping is provided for verification in the supplied PDF; the app does not redistribute the PDF.</p><p><a href="${esc(pdfUrl)}" target="_blank" rel="noopener noreferrer">Open official DOH-hosted PDF${pdfPage?' at PDF page '+esc(pdfPage):''} ↗</a></p>`;dialog.showModal();document.getElementById('closeSourceDialog').focus();}
const ORAL_PROMPTS=[
{id:'oral-framework',topic:'Strategic framework',title:'Explain the framework',prompt:'You are asked to explain how the Plan connects its vision, mission, goals, pillars, outcomes, and activities. Give a concise, structured response.',followups:['How would you explain the difference between an output and an outcome?','What would be an overstatement when describing this framework?'],model:'Describe the Plan’s stated hierarchy using its own terminology: vision and mission, the three goals, four pillars, and the outcomes with corresponding outputs and activities. Explain that outputs and activities are intended to contribute toward the goals, mission, and vision; this strategic logic is not proof that the intended outcomes were achieved.',checklist:['Uses the Plan’s stated hierarchy and terminology','Identifies the three goals and four pillars without inventing names','Distinguishes outputs/activities from outcomes','Avoids claiming that the framework proves impact'],printed:'27–38',pdf:'41–52',excerpt:'The Plan describes outcomes and corresponding outputs and activities under its pillars, contributing toward the goals, mission, and vision.',label:'learning-interpretation'},
{id:'oral-four-pillars',topic:'Four pillars',title:'Apply the four pillars',prompt:'A local planning group asks you to organize a mental health initiative using the Plan. Explain how you would use the four pillars to structure the discussion.',followups:['Would every local initiative need identical activities under every pillar? Why or why not?','What information would you verify locally before recommending implementation?'],model:'Name the four pillars: Promotion and Prevention; Leadership and Governance; Services; Information and Research. Use them as a planning structure to consider complementary activities, responsible parties, service delivery, and information needs. Treat specific local actions as proposals that require feasibility checks and local verification, not as direct requirements unless the Plan says so.',checklist:['Names all four pillars accurately','Explains how the pillars structure planning','Does not assume identical activities fit every setting','Separates Plan content from local implementation proposals'],printed:'27–38',pdf:'41–52',excerpt:'The strategic plan is organized around four pillars with associated outcomes, outputs, and activities.',label:'learning-interpretation'},
{id:'oral-historical-target',topic:'Source interpretation',title:'Defend a historical target',prompt:'During a presentation, a colleague states that a 2020–2023 target in the Plan was achieved because it appears in the document. How would you respond?',followups:['What is the difference between a target and a measured result?','What citation details should appear on the slide?'],model:'Clarify that a target states an intended level or direction, not proof of achievement. Label it as a historical target from the 2019–2023 Plan. To claim achievement or current performance, obtain separate implementation data with a relevant reporting period, source, and method of verification. Cite the printed and PDF pages.',checklist:['Identifies the target as historical','Distinguishes target from measured result','Requests separate evidence before claiming achievement','Includes printed and PDF page references'],printed:'27–38',pdf:'41–52',excerpt:'The Plan includes indicators, targets, responsible agencies, and modes of verification in its monitoring framework.',label:'learning-interpretation'},
{id:'oral-governance',topic:'Leadership and governance',title:'Respond to fragmented coordination',prompt:'A fictional local area has several providers but weak coordination. Outline a policy-level response using the Plan, and identify what you would need to verify.',followups:['How would you avoid assigning responsibilities not supported by the source?','What could be monitored to understand whether coordination is improving?'],model:'Use the Plan’s governance and service-integration framing to convene relevant local stakeholders, clarify responsibilities against authoritative documents, identify coordination gaps, and agree on feasible actions and monitoring. Treat a proposed indicator as a learning interpretation unless it is explicitly listed in the Plan. Verify local mandates, resources, and referral arrangements.',checklist:['Frames the problem as a coordination/system issue','Connects governance and services appropriately','Says responsibilities must be verified, not assumed','Proposes monitoring and notes indicator limitations'],printed:'34–36',pdf:'48–50',excerpt:'The Plan discusses service delivery and system-level implementation; local details must be verified against applicable current sources.',label:'learning-interpretation'},
{id:'oral-data',topic:'Information and research',title:'Critique a progress report',prompt:'A local report lists the number of awareness activities delivered but does not show who was reached or whether access changed. Critique the report and suggest next steps.',followups:['What is the difference between an activity count and an outcome measure?','What limitations should be stated when data are incomplete?'],model:'A count of activities is an implementation/output measure and by itself does not establish reach, improved access, or outcomes. Clarify the reporting period, intended audience, actual reach, geographic coverage, data source, and missingness. Select an indicator aligned with the question and define numerator/denominator where relevant. State data limitations and avoid causal claims unsupported by the design.',checklist:['Distinguishes activity from reach/access/outcome','Identifies missing data and reporting period','Defines a relevant indicator clearly','Notes limitations and avoids unsupported causal claims'],printed:'27–38',pdf:'41–52',excerpt:'The Plan’s monitoring framework includes indicators, targets, responsible agencies, and modes of verification.',label:'learning-interpretation'},
{id:'oral-financing',topic:'Implementation constraints',title:'Discuss a funding proposal',prompt:'A local group asks for a sustainable funding proposal but has no confirmed funding source. Explain how you would structure a responsible policy discussion.',followups:['How would you avoid implying that a funding source is guaranteed?','What evidence would support a feasibility recommendation?'],model:'Clarify the proposed activities, intended beneficiaries, responsible entities, recurring versus one-time costs, implementation capacity, governance and approval steps, and how use of resources would be monitored. Compare possible funding routes only after checking current rules and local budget processes. Do not present any source as guaranteed or attribute a specific financing mechanism to the Plan unless directly supported by it.',checklist:['Separates proposed costs from confirmed resources','Mentions governance/approval and sustainability','Includes implementation capacity and monitoring','Avoids assuming a funding source is guaranteed'],printed:'34–38',pdf:'48–52',excerpt:'Specific local financing availability and approval processes must be verified; a teaching proposal is not itself a source statement.',label:'learning-interpretation'}
];
